SERVICES = []
for (slug, name, tag, only_branch, desc), icon in zip(_SVC_SRC, _SVC_ICON):
    SERVICES.append(dict(
        slug=slug, name=name, tag=tag, icon=icon,
        short=desc, desc=f"{name} at Doctors Scans & Labs — {desc}",
        long=desc,
        points=[tag, "Reported by consultant specialists", "Same-day reporting where possible"],
        at=[only_branch] if only_branch else None,
    ))
for s in SERVICES:
    if s["at"] is None:
        s["at"] = [b["slug"] for b in BRANCHES]

def branches_for(service):
    return [b for b in BRANCHES if b["slug"] in service["at"]]

def services_for(branch):
    return [s for s in SERVICES if branch["slug"] in s["at"]]

