PACKAGES = []
def _slugify(s):
    import re as _re
    return _re.sub(r'-+', '-', _re.sub(r'[^a-z0-9]+', '-', s.lower())).strip('-')

for p in _pkg_raw:
    PACKAGES.append(dict(
        slug=_slugify(p["name"]),
        name=p["name"],
        category=p["cat"],
        badge=p["badge"],
        short=p["desc"],
        price=p["price"],
        orig=p["orig"],
        save=p.get("save"),
        testlabel=p["testlabel"],
        tests=p["tests"],
    ))

